/** static void SpriteCB_CountdownNumber(struct Sprite *sprite) */
export function SpriteCB_CountdownNumber(sprite: any): any {
  switch (sprite.sState)
      {
      case 0:
          sprite.sYPos += 8;
          if (sprite.sYPos > DISPLAY_HEIGHT / 2 + 8)
          {
              sprite.sYPos = DISPLAY_HEIGHT / 2 + 8;
              sprite.sState++;
              PlaySE(SE_BALL_BOUNCE_1);
          }
          break;
      case 1:
          if (++sprite.sDelay > 20)
          {
              sprite.sState++;
              sprite.sDelay = 0;
          }
          break;
      case 2:
          sprite.sYPos += 4;
          if (sprite.sYPos > DISPLAY_HEIGHT + 16)
          {
              if (++sprite.sAnimId == 3)
              {
                  DestroySprite(sprite);
                  CreateSprite(sSpriteTemplate_Start, 120, -20, 2);
              }
              else
              {
                  sprite.sState = 0;
                  sprite.sYPos = -16;
                  StartSpriteAnim(sprite, sprite.sAnimId);
              }
          }
          break;
      }

      sprite.y2 = sprite.sYPos;
}

/** static void SpriteCB_Start(struct Sprite *sprite) */
export function SpriteCB_Start(sprite: any): any {
  switch (sprite.data[0])
      {
      case 0:
          sprite.data[1] += 8;
          if (sprite.data[1] > 92)
          {
              sprite.data[1] = 92;
              sprite.data[0]++;
              PlaySE(SE_PIN);
          }
          break;
      case 1:
          sprite.data[2] += 1;
          if (sprite.data[2] > 20)
              sprite.data[0]++;
          break;
      case 2:
          sprite.data[1] += 4;
          if (sprite.data[1] > DISPLAY_HEIGHT + 16)
          {
              sBerryBlender.mainState++;
              DestroySprite(sprite);
          }
          break;
      }

      sprite.y2 = sprite.data[1];
}

/** static void TryUpdateProgressBar(u16 current, u16 limit) */
export function TryUpdateProgressBar(current: any, limit: any): any {
  if (sBerryBlender.maxProgressBarValue < current)
      {
          sBerryBlender.maxProgressBarValue += 2;
          UpdateProgressBar(sBerryBlender.maxProgressBarValue, limit);
      }
}

/** static void UpdateProgressBar(u16 value, u16 limit) */
export function UpdateProgressBar(value: any, limit: any): any {
  let amountFilled, maxFilledSegment, subSegmentsFilled, i;
      let vram: any = null;

      vram = (BG_SCREEN_ADDR(12));
      amountFilled = (value * 64) / limit;
      maxFilledSegment = amountFilled / 8;

       
      for (i = 0; i < maxFilledSegment; i++)
      {
          vram[11 + i] = (0x80E9);
          vram[43 + i] = (0x80F9);
      }

       
      subSegmentsFilled = amountFilled % 8;
      if (subSegmentsFilled != 0)
      {
          vram[11 + i] = subSegmentsFilled + (0x80E1);
          vram[43 + i] = subSegmentsFilled + (0x80F1);
          i++;
      }

       
       
      for (; i < 8; i++)
      {
          vram[11 + i] = (0x80E1);
          vram[43 + i] = (0x80F1);
      }
}

/** static u32 ArrowSpeedToRPM(u16 speed) */
export function ArrowSpeedToRPM(speed: any): any {
  return 60 * 60 * 100 * speed / (0x10000);
}

/** static void UpdateRPM(u16 speed) */
export function UpdateRPM(speed: any): any {
  let i: any = null;
      let digits: any = [];

       
      let currentRPM: any = ArrowSpeedToRPM(speed);
      if (sBerryBlender.maxRPM < currentRPM)
          sBerryBlender.maxRPM = currentRPM;

       
      for (i = 0; i < 5; i++)
      {
          digits[i] = currentRPM % 10;
          currentRPM /= 10;
      }
      MEM_WRITE(((BG_SCREEN_ADDR(12) + 0x458)), digits[4] + (0x8072));
      MEM_WRITE(((BG_SCREEN_ADDR(12) + 0x45A)), digits[3] + (0x8072));
      MEM_WRITE(((BG_SCREEN_ADDR(12) + 0x45C)), digits[2] + (0x8072));
      MEM_WRITE(((BG_SCREEN_ADDR(12) + 0x460)), digits[1] + (0x8072));
      MEM_WRITE(((BG_SCREEN_ADDR(12) + 0x462)), digits[0] + (0x8072));
}

/** static void ShakeBgCoordForHit(s16 *coord, u16 speed) */
export function ShakeBgCoordForHit(coord: any, speed: any): any {
  if (coord == 0)
          coord = (Random() % speed) - (speed / 2);
}

/** static void RestoreBgCoord(s16 *coord) */
export function RestoreBgCoord(coord: any): any {
  if (coord < 0)
          coord++;
      if (coord > 0)
          coord--;
}

/** static void RestoreBgCoords(void) */
export function RestoreBgCoords(): any {
  RestoreBgCoord(sBerryBlender.bg_X);
      RestoreBgCoord(sBerryBlender.bg_Y);
}

/** static void BlenderLandShakeBgCoord(s16 *coord, u16 timer) */
export function BlenderLandShakeBgCoord(coord: any, timer: any): any {
  let strength: any = null;

      if (timer < 10)
          strength = 16;
      else
          strength = 8;

      if (coord == 0)
      {
          coord = (Random() % strength) - (strength / 2);
      }
      else
      {
          if (coord < 0)
              coord++;
          if (coord > 0)
              coord--;
      }
}

/** static bool8 UpdateBlenderLandScreenShake(void) */
export function UpdateBlenderLandScreenShake(): any {
  if (sBerryBlender.framesToWait == 0)
      {
          sBerryBlender.bg_X = 0;
          sBerryBlender.bg_Y = 0;
      }

      sBerryBlender.framesToWait++;
      BlenderLandShakeBgCoord(sBerryBlender.bg_X, sBerryBlender.framesToWait);
      BlenderLandShakeBgCoord(sBerryBlender.bg_Y, sBerryBlender.framesToWait);

      if (sBerryBlender.framesToWait == 20)
      {
          sBerryBlender.bg_X = 0;
          sBerryBlender.bg_Y = 0;
          return TRUE;
      }

      return FALSE;
}

